import { generatePrivateKey } from "viem/accounts";
import { ARBITRUM, getViemChain } from "../../../configs/chains";
import { sleep } from "../../../utils/common";
import { PrivateKeySigner } from "../../../utils/signer";
import { GmxApiSdk } from "../index";
export const TEST_CHAIN_ID = ARBITRUM;
export const TEST_SYMBOL = "ETH/USD [WETH-USDC]";
export const TEST_SIZE_USD = 10n * 10n ** 30n; // $10
// Must clear MIN_COLLATERAL_USD ($1 on Arbitrum) after fees, or the keeper cancels the order.
export const TEST_COLLATERAL = { amount: 3000000n, token: "USDC" }; // 3 USDC
const TERMINAL_STATUSES = new Set(["executed", "cancelled", "relay_failed", "relay_reverted"]);
// A limit or conditional order rests at "created" until its trigger is hit.
const PLACED_STATUSES = new Set([...TERMINAL_STATUSES, "created"]);
export const PLACED_OK_STATUSES = ["created", "executed"];
const ORDER_PREPARE_PATHS = new Set([
    "/v1/orders/txns/prepare",
    "/v1/orders/txns/edit/prepare",
    "/v1/orders/txns/cancel/prepare",
    "/v1/orders/txns/collateral/prepare",
]);
export class RecordingApi {
    constructor(delegate) {
        this.delegate = delegate;
        this.orderPrepareRequests = [];
        this.orderSubmitRequests = [];
        this.url = delegate.url;
    }
    fetchJson(path, opts) {
        return this.delegate.fetchJson(path, opts);
    }
    postJson(path, body, opts) {
        if (ORDER_PREPARE_PATHS.has(path)) {
            this.orderPrepareRequests.push(body);
        }
        else if (path === "/v1/orders/txns/submit") {
            this.orderSubmitRequests.push(body);
        }
        return this.delegate.postJson(path, body, opts);
    }
}
export function buildPreparedOrderResponse(requestId) {
    return {
        requestId,
        mode: "express",
        payloadType: "typed-data",
        payload: {
            batchParams: {},
            relayParams: {},
        },
    };
}
export class ScriptedOrderApi {
    constructor(prepareResponse, submitResponses = [], subaccountStatusResponses = []) {
        this.prepareResponse = prepareResponse;
        this.submitResponses = submitResponses;
        this.subaccountStatusResponses = subaccountStatusResponses;
        this.url = "http://test";
        this.prepareRequests = [];
        this.submitRequests = [];
        this.subaccountStatusRequests = [];
    }
    fetchJson(path, _opts) {
        return Promise.reject(new Error(`Unexpected fetchJson call ${path}`));
    }
    postJson(path, body, opts) {
        if (path === "/v1/orders/txns/prepare") {
            this.prepareRequests.push(body);
            return Promise.resolve(opts?.transform ? opts.transform(this.prepareResponse) : this.prepareResponse);
        }
        if (path === "/v1/orders/txns/submit") {
            this.submitRequests.push(body);
            const response = this.submitResponses.shift();
            if (!response) {
                return Promise.reject(new Error("Unexpected submit call"));
            }
            return Promise.resolve(response);
        }
        if (path === "/v1/subaccounts/status") {
            this.subaccountStatusRequests.push(body);
            const response = this.subaccountStatusResponses.shift();
            if (!response) {
                return Promise.reject(new Error("Unexpected subaccount status call"));
            }
            return Promise.resolve(response);
        }
        return Promise.reject(new Error(`Unexpected API path ${path}`));
    }
}
export function buildSubaccountStatusResponse(overrides = {}) {
    return {
        active: true,
        maxAllowedCount: "10",
        currentActionsCount: "0",
        remainingActions: "10",
        expiresAt: String(Math.floor(Date.now() / 1000) + 86400),
        approvalNonce: "0",
        multichainApprovalNonce: "0",
        integrationId: null,
        ...overrides,
    };
}
export function getTestSdk() {
    // eslint-disable-next-line no-restricted-globals
    const apiUrl = process.env.GMX_TEST_API_URL;
    return new GmxApiSdk({ chainId: TEST_CHAIN_ID, ...(apiUrl && { apiUrl }) });
}
export function getTestSigner() {
    // eslint-disable-next-line no-restricted-globals
    const pk = process.env.GMX_TEST_PRIVATE_KEY;
    if (!pk)
        return undefined;
    // eslint-disable-next-line no-restricted-globals
    const rpcUrl = process.env.GMX_TEST_RPC_URL;
    return new PrivateKeySigner(pk, rpcUrl ? { rpcUrl, chain: getViemChain(TEST_CHAIN_ID) } : undefined);
}
export function requireSigner() {
    const signer = getTestSigner();
    if (!signer) {
        throw new Error("GMX_TEST_PRIVATE_KEY env var is required for this test");
    }
    return signer;
}
let ephemeralSigner;
export function getOrCreateTestSigner() {
    const signer = getTestSigner();
    if (signer)
        return signer;
    if (!ephemeralSigner) {
        ephemeralSigner = new PrivateKeySigner(generatePrivateKey());
    }
    return ephemeralSigner;
}
// TWAP fans out into one paid sub-order per part, so the live flows are opt-in.
export function shouldRunTwap() {
    // eslint-disable-next-line no-restricted-globals
    return process.env.GMX_TEST_TWAP === "1";
}
// Concurrent prepares are priced moments apart, so oracle-derived values drift in the last digits.
export function withinOneBp(a, b) {
    const diff = a > b ? a - b : b - a;
    return diff * 10000n <= a;
}
export function hasRpcUrl() {
    // eslint-disable-next-line no-restricted-globals
    return !!process.env.GMX_TEST_RPC_URL;
}
/** For limit and conditional orders: resolves as soon as the order is on the book. */
export function waitForOrderPlaced(sdk, requestId, timeoutMs = 60000) {
    return waitForOrderStatus(sdk, requestId, timeoutMs, PLACED_STATUSES);
}
export async function waitForOrderStatus(sdk, requestId, timeoutMs = 60000, stopStatuses = TERMINAL_STATUSES) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const status = await sdk.fetchOrderStatus({ requestId });
        if (stopStatuses.has(status.status)) {
            if (!PLACED_OK_STATUSES.includes(status.status)) {
                logOrderFailure(status);
            }
            return status;
        }
        await sleep(2000);
    }
    return sdk.fetchOrderStatus({ requestId });
}
function logOrderFailure(status) {
    const parts = [`[order:${status.status}]`, `id=${status.requestId}`];
    if (status.error) {
        parts.push(`error=${status.error.code}: ${status.error.message}`);
    }
    if (status.cancellationReason) {
        parts.push(`reason=${status.cancellationReason}`);
    }
    if (status.traceId) {
        parts.push(`trace=${status.traceId}`);
    }
    if (status.taskId) {
        parts.push(`task=${status.taskId}`);
    }
    if (status.createdTxnHash) {
        parts.push(`createTx=${status.createdTxnHash}`);
    }
    if (status.executionTxnHash) {
        parts.push(`execTx=${status.executionTxnHash}`);
    }
    // eslint-disable-next-line no-console
    console.warn(parts.join(" "));
}
export async function expressFlow(sdk, signer, request) {
    const prepared = await sdk.prepareOrder(request);
    const signature = await sdk.signOrder(prepared, signer);
    const submitted = await sdk.submitOrder({
        mode: prepared.mode,
        requestId: prepared.requestId,
        signature,
        from: signer.address,
        idempotencyKey: prepared.idempotencyKey,
        eip712Data: {
            batchParams: prepared.payload.batchParams,
            relayParams: prepared.payload.relayParams,
            subaccountApproval: request.subaccountApproval,
        },
    });
    return { prepared, signature, submitted };
}
export async function waitForOrdersUpdate(sdk, account, predicate, timeoutMs = 15000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        await sleep(2000);
        const orders = await sdk.fetchOrders({ address: account });
        if (predicate(orders))
            return orders;
    }
    return sdk.fetchOrders({ address: account });
}
export async function waitForPositionUpdate(sdk, account, predicate, timeoutMs = 15000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        await sleep(2000);
        const positions = await sdk.fetchPositionsInfo({ address: account });
        if (predicate(positions))
            return positions;
    }
    // Final attempt
    return sdk.fetchPositionsInfo({ address: account });
}
export async function activateTestSubaccount(sdkSub, signer, account) {
    const subAddr = await sdkSub.generateSubaccount(signer);
    const status = await sdkSub.fetchSubaccountStatus({ account, subaccountAddress: subAddr });
    const maxAllowedCount = Number(status.currentActionsCount) + 50;
    await sdkSub.activateSubaccount(signer, {
        expiresInSeconds: 86400,
        maxAllowedCount,
    });
}
